def _attrs_to_script(attrs):
    """
    Return a valid Python script of an initializer for *attrs*.

    Validators -- if any -- are called on the value *before* it is set on the
    instance.  Therefore a failing validator prevents the instance from being
    created at all.
    """
    lines = []
    args = []
    for a in attrs:
        def validate(value, a=a):
            """
            Return a line that calls the validator of attribute *a* -- if it
            has one.
            """
            if a.validator is None:
                return ""
            return 'attr_dict["{name}"].validator({value})'.format(
                name=a.name, value=value
            )

        if a.default_value is not NOTHING:
            args.append("{name}={default!r}".format(name=a.name,
                                                    default=a.default_value))
            lines.extend([
                validate(a.name),
                "self.{name} = {name}".format(name=a.name),
            ])
        elif a.default_factory is not NOTHING:
            args.append("{name}=NOTHING".format(name=a.name))
            lines.append("{name} = self.{name} = ("
                         "{name} if {name} is not NOTHING else "
                         'attr_dict["{name}"].default_factory())'.format(
                             name=a.name
                         ))
        else:
            args.append(a.name)
            lines.extend([
                validate(a.name),
                "self.{name} = {name}".format(name=a.name),
            ])

    return """\
def __init__(self, {args}):
    '''
    Attribute initializer automatically created by attrs.
    '''
    {setters}
""".format(
        args=", ".join(args),
        setters="\n    ".join(
            line for line in lines if line
        ),
    )

